/** Public entry point — the only module consumers/docs should import from. */

export {
  useDataGridServerRows,
  type UseDataGridServerRowsOptions,
  type UseDataGridServerRowsResult,
  type ServerRowsPageRequest,
  type ServerRowsRequest,
  type ServerRowsAnswer,
  type DataSourceState,
  type UseDataGridServerRowsScrollOptions,
  type UseDataGridServerRowsScrollResult,
} from "./use-data-grid-server-rows";

import type { RowRange } from "@/registry/default/components/data-grid/data-grid";

/** `end - start`, clamped to 0 for an inverted/empty range. */
export function rangeSize(range: RowRange): number {
  return Math.max(0, range.end - range.start);
}

/** Whether two half-open ranges overlap or touch at an edge (touching ranges are mergeable). */
function rangesAdjacentOrOverlapping(a: RowRange, b: RowRange): boolean {
  return a.start <= b.end && b.start <= a.end;
}

/**
 * Expands `range` by `overscan` rows on each side, then rounds outward so both edges land on a
 * `blockSize` boundary — small scrolls request the same batch repeatedly instead of a slightly
 * different range every tick (spec: "round ranges up so tiny scrolls don't spam requests").
 * Clamps to `[0, total]`.
 */
export function expandRange(range: RowRange, opts: { overscan: number; blockSize: number; total?: number }): RowRange {
  const { overscan, blockSize, total = Infinity } = opts;
  const withOverscan = { start: range.start - overscan, end: range.end + overscan };
  const batch = Math.max(1, blockSize);
  const start = Math.floor(withOverscan.start / batch) * batch;
  const end = Math.ceil(withOverscan.end / batch) * batch;
  return {
    start: Math.max(0, start),
    end: Math.min(total, Math.max(start, end)),
  };
}

/**
 * Subtracts every range in `covered` (already loaded or in-flight, any order/overlap) from
 * `target`, returning the remaining uncovered pieces coalesced into as few ranges as possible —
 * this is the "never re-request a loading/loaded range; merge adjacent gaps" rule as pure math.
 */
export function subtractRanges(target: RowRange, covered: readonly RowRange[]): RowRange[] {
  if (rangeSize(target) === 0) return [];
  const relevant = covered
    .filter((r) => rangeSize(r) > 0 && rangesAdjacentOrOverlapping(r, target))
    .map((r) => ({ start: Math.max(r.start, target.start), end: Math.min(r.end, target.end) }))
    .sort((a, b) => a.start - b.start);

  const merged: RowRange[] = [];
  for (const r of relevant) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) {
      last.end = Math.max(last.end, r.end);
    } else {
      merged.push({ ...r });
    }
  }

  const gaps: RowRange[] = [];
  let cursor = target.start;
  for (const r of merged) {
    if (r.start > cursor) gaps.push({ start: cursor, end: r.start });
    cursor = Math.max(cursor, r.end);
  }
  if (cursor < target.end) gaps.push({ start: cursor, end: target.end });
  return gaps;
}

/** Sum of `rangeSize` across a list of ranges — callers pass an already-merged (disjoint) list so this is a true row count, not a double-count of overlaps. */
export function sumRangeSizes(ranges: readonly RowRange[]): number {
  return ranges.reduce((total, r) => total + rangeSize(r), 0);
}

/**
 * Splits `range` into consecutive chunks of at most `max` rows, covering it exactly once; a
 * single chunk when the range already fits. Each chunk obeys the `fetchRows` contract on its
 * own: exactly `chunk.end - chunk.start` rows, positionally aligned to `chunk.start`. A
 * fractional `max` is rounded down so every chunk boundary stays an integral row index.
 */
export function chunkRange(range: RowRange, max: number): RowRange[] {
  const size = rangeSize(range);
  const cap = Math.max(1, Math.floor(max));
  if (size <= cap) return [range];
  const chunks: RowRange[] = [];
  for (let start = range.start; start < range.end; start += cap) {
    chunks.push({ start, end: Math.min(range.end, start + cap) });
  }
  return chunks;
}

/** Merges a list of ranges (any order/overlap) into the minimal set of disjoint, non-touching ranges. */
export function mergeRanges(ranges: readonly RowRange[]): RowRange[] {
  const sorted = ranges
    .filter((r) => rangeSize(r) > 0)
    .slice()
    .sort((a, b) => a.start - b.start);
  const merged: RowRange[] = [];
  for (const r of sorted) {
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) {
      last.end = Math.max(last.end, r.end);
    } else {
      merged.push({ ...r });
    }
  }
  return merged;
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { applyChange, serverSpecKey, type DataChange, type DataGridPlugin, type FilterNode, type RowRange, type ServerSpec, type SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { holeRowId, isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { readAnswer, type ReadAnswer, type ServerRowsAnswer, type ServerRowsRequest } from "./read-answer";
import { GUARD_MISSING_MESSAGE, pruneIds, stashGuardedRows, trackDeletes, unionIds, useRefreshGuard, writeBlocks, type GuardedBlock, type ProtectedRows } from "./refresh-guard";
import { cursorKey, MAX_SEEN_CURSORS, needsNextBlock, skeletonCount, startsSequence, stepSequence } from "./scroll-sequence";
import { chunkRange, expandRange, mergeRanges, rangeSize, subtractRanges, sumRangeSizes } from "./range-math";
import { isolate, useServerSpec } from "./server-state";
import type { UseDataGridServerRowsRootProps } from "./use-data-grid-server-rows";

const DEFAULT_OVERSCAN = 30;
const DEFAULT_BLOCK_SIZE = 50;

/** Options of `useDataGridServerRows` in scroll mode. */
export type UseDataGridServerRowsScrollOptions<TData, TCursor = never> = {
  /** `"scroll"` fetches fixed-size blocks as the rendered rows move. Fixed for the life of the hook. */
  mode: "scroll";
  getRowId: (row: TData, index: number) => string;
  /**
   * Resolves rows `[start, end)` of the result. The first answer picks the fetch order:
   * - `totalRowCount` and no `nextCursor`: random access. The grid sizes its rows from the count, and a changed count starts the blocks over.
   * - `nextCursor` (with or without a count), or neither: sequential. The grid shows the loaded rows plus one block of skeletons, and
   *   the next block starts when the rendered rows come near the end. `nextCursor` comes back as `cursor`; `nextCursor: null`,
   *   `hasMore: false`, or an empty block ends the source. Without a cursor, `hasMore` defaults to a full block.
   */
  fetchRows: (request: ServerRowsRequest<TCursor>) => Promise<ServerRowsAnswer<TData, TCursor>>;
  /** The sort, filter, and search while `spec` is not controlled. */
  defaultSpec?: Partial<ServerSpec>;
  /** Controls the sort, filter, and search; pair it with `onSpecChange`. A content change starts the blocks over. */
  spec?: ServerSpec;
  onSpecChange?: (spec: ServerSpec) => void;
  /** Rows per request. Requests align to multiples of it, so small scrolls reuse the same block. Default 50. */
  blockSize?: number;
  /** Rows fetched beyond the rendered rows on each side. Default 30. */
  overscan?: number;
  /** Fires after a request fails. */
  onError?: (error: unknown) => void;
  /** Fires after the rows of a block land, with the range they cover. The grid shows them on the next frame. */
  onLoaded?: (range: RowRange) => void;
  /** Fires after the hook merged an edit, insert, delete, or revert. Put your handler here; a spread override drops the merge. */
  onDataChange?: (next: readonly TData[], change: DataChange<TData>) => void;
};

/** Props of {@link UseDataGridServerRowsScrollResult.gridProps} that belong to `DataGridProvider`. */
export type UseDataGridServerRowsScrollProviderProps<TData> = {
  /** Sparse at runtime: an unloaded row is a hole, typed as `TData` to match `DataGridProps`. */
  data: readonly TData[];
  /** Gives an unloaded row a placeholder id and a loaded row its own. */
  getRowId: (row: TData, index: number) => string;
  /** Keeps the rows in step with edits, inserts, deletes, and reverts of a refused save. Send changes to your API from `onSave`. */
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  /** Reports the rendered rows so the hook can fetch the blocks they need. */
  onRenderedRowsChange: (range: RowRange) => void;
  sortMode: "server";
  filterMode: "server";
  sortState: SortSpec[];
  onSortChange: (next: SortSpec[]) => void;
  filterState: FilterNode[];
  onFilterChange: (next: FilterNode[]) => void;
  searchText: string;
  onSearchTextChange: (next: string) => void;
  /** The row count of the result; `null` until the first block lands, and for a sequential source until it ends or the server sends one. */
  totalRowCount: number | null;
  keepCheckedRows: true;
  /** Mounts the guard that keeps a refresh from overwriting a row with a pending save or an open edit. Put your own plugins after it. */
  plugins: readonly DataGridPlugin<unknown>[];
};

/** Return value of `useDataGridServerRows` in scroll mode. */
export type UseDataGridServerRowsScrollResult<TData> = {
  /** Spread onto `<DataGrid {...server.gridProps} columns={columns} />`. */
  gridProps: UseDataGridServerRowsScrollProviderProps<TData> & UseDataGridServerRowsRootProps;
  /** The part of `gridProps` for `<DataGridProvider>` in a composed layout. */
  providerProps: UseDataGridServerRowsScrollProviderProps<TData>;
  /** The part of `gridProps` for `<DataGridRoot>` in a composed layout: the loading flag and the error state. */
  rootProps: UseDataGridServerRowsRootProps;
  /** The sort, filter, and search text of the current requests. */
  spec: ServerSpec;
  /** The row count of the result; `null` until the first block lands, and for a sequential source until it ends or the server sends one. */
  totalRowCount: number | null;
  /** `"error"` wins over `"loading"`. */
  status: "loading" | "error" | "ready";
  /** A request of the current spec is in flight. */
  loading: boolean;
  /** The latest failure of the current spec that no landed block has replaced, or `null`. */
  error: unknown;
  /** Repeats the blocks that failed. Does nothing without an error. */
  retry: () => void;
  /**
   * Fetches the rendered rows again and keeps them on screen until the answers land. Drops every other loaded row. A sequential
   * source refetches from the first block up to the rendered rows. A block that lands (refresh, retry or window load) replaces every row it carries, except a row that has a pending cell edit or a save that was in flight at any moment since the request was sent: that row keeps its local value. A row with a pending delete is gone: the answer's copy is dropped and its slot stays empty. A protected row that the answer lacks, such as a pending insert, returns to its own slot when no answer row sits there; otherwise it is hidden, and a counted source refreshes when no pending insert or delete is left, so the server decides. A pages refresh appends such a row at the end of the page, so the page can exceed `pageSize` by pending inserts. A sequential refresh that ends before a pending insert may drop it until its save settles. A block shows each id once (the first row of a repeated id in an answer wins) and leaves no hole in its loaded range; rows that moved on the server can mix with older rows until the next refresh settles.
   * Call it after the `onSave` promise settles to pick up server-computed fields.
   */
  refresh: () => void;
  /** Rows with no data yet; they render as skeletons. A sequential source reports its one block of skeletons. */
  unloadedCount: number;
  /** The loaded ranges, merged and ascending. Not reactive: read it in an effect or a handler. */
  getLoadedRanges: () => readonly RowRange[];
  /** Unloads the rows in `range`; the next rendered window that covers them fetches them again. Does nothing on a sequential source. */
  evict: (range: RowRange) => void;
};

type Pending<TData> = GuardedBlock<TData> & { rows: (TData | undefined)[]; mark: number; final?: boolean };
/** `guard` is the set of rows protected when the request started; a retry reuses it. */
type Guard = { ids: ProtectedRows; /** The save count when the request started; later saves are protected too. */ mark: number };
type InFlight = { range: RowRange; controller: AbortController; guard: Guard };
type Failed = { range: RowRange; cursor: unknown; error: unknown };

type Sequence = {
  /** The cursor the next block sends. */
  cursor: unknown;
  ended: boolean;
  /** Rows loaded, without the skeleton rows below them. */
  length: number;
  /** Where the next request starts: the rows the server answered, which exceed `length` by the protected rows dropped from appended blocks. */
  offset: number;
  /** The count the server sent, if any. */
  sentCount: number | null;
  /** A refresh rewrites the rows in place from the first block until the chain passes `keepUntil`. */
  refresh: { keepUntil: number; local: number } | null;
  /** Keys of the cursors the chain returned so far. */
  seen: Set<string>;
};

const freshSequence = (): Sequence => ({ cursor: undefined, ended: false, length: 0, offset: 0, sentCount: null, refresh: null, seen: new Set() });

type Core<TData> = {
  count: number | null;
  /** The first block of the current spec landed. */
  ready: boolean;
  loaded: RowRange[];
  /** Decided by the first answer of the current spec. */
  kind: "unknown" | "random" | "sequence";
  seq: Sequence;
  inFlight: Map<string, InFlight>;
  failed: Map<string, Failed>;
  pending: Pending<TData>[];
  cancelFrame: (() => void) | null;
  lastWindow: RowRange | null;
  rowsLength: number;
  warned: Set<string>;
  /** Guarded rows an earlier block overwrote, for the block that brings their id back; empty when no request is pending. */
  displaced: Map<string, TData>;
  /** Protected rows that are not loaded (dropped by a spec change or deleted locally); a block that carries one keeps its incoming copy. */
  absent: Set<string>;
  /** Ranges whose rows a local row operation moved: not loaded, but a protected row may still sit there. A landing block or an eviction removes them. */
  stale: RowRange[];
  /** Protected rows that a block overwrote, and the ids the landed blocks carried; both are emptied when no request is pending. */
  orphans: Map<string, { row: TData; slot: number }>;
  carried: Set<string>;
  /** Cancels the refresh that a burst of local row operations queued for the next frame. */
  cancelQueuedRefresh: (() => void) | null;
  /** Rows with a delete still saving: an answer that carries one drops it. */
  deleted: Set<string>;
  /** Slots an answer left empty on purpose (a repeated or deleted row): answered, never refetched, never claimed as loaded. */
  empty: RowRange[];
  /** Slots a protected row moved away from; `core.loaded` stops claiming them. */
  cleared: Set<number>;
};

function createCore<TData>(): Core<TData> {
  return { count: null, ready: false, loaded: [], kind: "unknown", seq: freshSequence(), inFlight: new Map(), failed: new Map(), pending: [], cancelFrame: null, lastWindow: null, rowsLength: 0, warned: new Set(), displaced: new Map(), absent: new Set(), deleted: new Set(), cancelQueuedRefresh: null, orphans: new Map(), carried: new Set(), empty: [], stale: [], cleared: new Set() };
}

function scheduleFrame(callback: () => void): () => void {
  if (typeof requestAnimationFrame === "function") {
    const id = requestAnimationFrame(callback);
    return () => cancelAnimationFrame(id);
  }
  const id = setTimeout(callback, 16);
  return () => clearTimeout(id);
}

function oldestMark<TData>(core: Core<TData>): number | null {
  let oldest: number | null = null;
  const note = (mark: number) => {
    if (oldest === null || mark < oldest) oldest = mark;
  };
  for (const { guard } of core.inFlight.values()) note(guard.mark);
  for (const { mark } of core.pending) note(mark);
  return oldest;
}

/** Keeps the entries of rows that are still protected: a queued commit may still read or fill the map. */
function forgetDisplacedWhenIdle<TData>(core: Core<TData>, stillProtected: ProtectedRows) {
  if (oldestMark(core) !== null) return;
  for (const id of core.displaced.keys()) if (!stillProtected?.has(id)) core.displaced.delete(id);
  core.orphans = new Map();
  core.carried = new Set();
}

function commitOnFrame<TData>(core: Core<TData>, commit: () => void, onIdle: () => void) {
  if (core.cancelFrame !== null) return;
  commit();
  core.cancelFrame = scheduleFrame(() => {
    core.cancelFrame = null;
    if (core.pending.length > 0) commitOnFrame(core, commit, onIdle);
    else onIdle();
  });
}

const rangeKey = (range: RowRange) => `${range.start}:${range.end}`;

function positiveInteger(value: number | undefined, fallback: number, min: number): number {
  return typeof value === "number" && Number.isFinite(value) ? Math.max(min, Math.floor(value)) : fallback;
}

/** Scroll mode of `useDataGridServerRows`: random access over a counted result, or a sequential chain of blocks. */
export function useScrollBlocks<TData, TCursor = never>(options: UseDataGridServerRowsScrollOptions<TData, TCursor>): UseDataGridServerRowsScrollResult<TData> {
  const { spec, onSortChange, onFilterChange, onSearchTextChange } = useServerSpec(options, noop);
  const coreRef = useRef<Core<TData> | null>(null);
  const getCore = useCallback((): Core<TData> => {
    if (coreRef.current === null) coreRef.current = createCore<TData>();
    return coreRef.current;
  }, []);
  const [rows, setRows] = useState<(TData | undefined)[]>([]);
  const [count, setCount] = useState<number | null>(null);
  const [loadedCount, setLoadedCount] = useState(0);
  const [skeletons, setSkeletons] = useState<number | null>(null);
  const { plugins, protectedRows, savingRows, guardMissing, markEdited, saveMark, savedSince, pruneSaves, setSettleListener, forgetStructural } = useRefreshGuard();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);
  const live = useRef({ options, spec });
  useLayoutEffect(() => {
    live.current = { options, spec };
  });

  const warn = useCallback(
    (kind: string, message: string) => {
      const core = getCore();
      if (!isDev() || core.warned.has(kind)) return;
      core.warned.add(kind);
      console.warn(`[data-grid-server] ${message}`);
    },
    [getCore],
  );
  const blockSize = useCallback(() => positiveInteger(live.current.options.blockSize, DEFAULT_BLOCK_SIZE, 1), []);
  const overscanOf = useCallback(() => positiveInteger(live.current.options.overscan, DEFAULT_OVERSCAN, 0), []);
  const notifyLoaded = useCallback((start: number, end: number) => {
    const onLoaded = live.current.options.onLoaded;
    if (end > start && onLoaded) isolate("onLoaded", () => onLoaded({ start, end }));
  }, []);

  const release = useCallback(
    (core: Core<TData>) => {
      forgetDisplacedWhenIdle(core, protectedRows());
      pruneSaves(oldestMark(core));
      if (oldestMark(core) === null) {
        pruneIds(core.deleted, savingRows());
        pruneIds(core.absent, savingRows());
      }
    },
    [pruneSaves, protectedRows, savingRows],
  );

  const commit = useCallback(() => {
    const core = getCore();
    const pending = core.pending.splice(0);
    if (pending.length === 0) return;
    const batch = pending.map(({ start, rows, guard, mark }) => ({ start, rows, guard: unionIds(guard, savedSince(mark)) }));
    const final = pending[pending.length - 1]!.final === true || core.inFlight.size === 0;
    const displaced = core.displaced;
    const memory = { orphans: core.orphans, carried: core.carried };
    const length = core.kind === "sequence" ? core.rowsLength : null;
    const guarded = protectedRows();
    // A sequential refresh shrinks `loaded` at its end, before the commit, so it scans the whole dense array.
    const ranges = core.kind === "sequence" ? [{ start: 0, end: Number.MAX_SAFE_INTEGER }] : core.stale.length > 0 ? mergeRanges([...core.loaded, ...core.stale]) : core.loaded;
    const idOf = live.current.options.getRowId;
    setRows((prev) => {
      const base = length === null ? prev : Object.assign(prev.slice(), { length });
      const written = writeBlocks(base, batch, guarded, displaced, ranges, idOf, memory, final);
      for (const slot of written.cleared) core.cleared.add(slot);
      return written.rows;
    });
  }, [getCore, protectedRows, savedSince]);

  // The first landing commits at once; later ones wait for the next frame, so a burst costs one copy of the rows per frame.
  const commitSoon = useCallback(
    () =>
      commitOnFrame(getCore(), commit, () => {
        const core = getCore();
        release(core);
        setLoading(core.inFlight.size > 0);
      }),
    [getCore, commit, release],
  );

  const abortRequests = useCallback(() => {
    const core = getCore();
    for (const { controller } of core.inFlight.values()) controller.abort();
    core.inFlight.clear();
  }, [getCore]);

  const dropBlocks = useCallback(
    (size: number) => {
      const core = getCore();
      const hadRows = core.loaded.length > 0 || core.stale.length > 0 || core.pending.length > 0;
      abortRequests();
      core.kind = "unknown";
      core.seq = freshSequence();
      setSkeletons(null);
      core.loaded = [];
      core.failed.clear();
      core.pending.length = 0;
      pruneSaves(null);
      forgetStructural();
      core.cancelQueuedRefresh?.();
      core.cancelQueuedRefresh = null;
      core.displaced = new Map();
      core.stale = [];
      core.empty = [];
      core.absent = new Set(savingRows() ?? []);
      core.cleared.clear();
      core.cancelFrame?.();
      core.cancelFrame = null;
      if (core.rowsLength !== size || hadRows) setRows(new Array<TData | undefined>(size));
      core.rowsLength = size;
      setLoadedCount(0);
    },
    [getCore, abortRequests, pruneSaves, savingRows, forgetStructural],
  );

  const windowRef = useRef<(range: RowRange) => void>(noop);

  const runFetchRef = useRef<(range: RowRange, cursor?: unknown) => void>(noop);

  const landSequence = useCallback(
    (range: RowRange, read: ReadAnswer<TData, unknown>, sentCursor: unknown, guard: Guard) => {
      const core = getCore();
      const seq = core.seq;
      const size = blockSize();
      core.ready = true;
      core.kind = "sequence";
      if (typeof read.totalRowCount === "number") seq.sentCount = read.totalRowCount;
      else if (read.totalRowCount === null) seq.sentCount = null;
      const refresh = seq.refresh;
      const at = refresh ? refresh.local : seq.length;
      const idOf = live.current.options.getRowId;
      const serverLength = Math.min(read.rows.length, range.end - range.start);
      const guarded = refresh ? null : unionIds(unionIds(guard.ids, savedSince(guard.mark)), protectedRows());
      const incoming: TData[] = [];
      read.rows.slice(0, serverLength).forEach((row, index) => {
        if (row === undefined) return;
        const id = idOf(row, range.start + index);
        if (core.deleted.has(id)) return;
        if (guarded !== null && guarded.has(id) && !core.absent.has(id) && !core.displaced.has(id)) return;
        incoming.push(row);
      });
      if (core.absent.size > 0) read.rows.forEach((row, index) => row !== undefined && core.absent.delete(idOf(row, range.start + index)));
      const written = incoming.length;
      const position = at + written;
      const serverPosition = range.start + serverLength;
      const step = stepSequence({ read, sentCursor, loaded: serverPosition, count: seq.sentCount, seenCursors: seq.seen });
      if (step.warning) warn(step.warning.kind, step.warning.message);
      for (const [key, failure] of core.failed) {
        if (failure.range.start === range.start) core.failed.delete(key);
      }
      if (core.failed.size === 0) setError(null);
      seq.cursor = step.cursor;
      const returned = cursorKey(step.cursor);
      if (returned !== null && seq.seen.size < MAX_SEEN_CURSORS) seq.seen.add(returned);
      core.pending.push({ start: at, rows: incoming, guard: guard.ids, mark: guard.mark });
      if (refresh && !step.ended && position < refresh.keepUntil) {
        core.rowsLength = Math.max(core.rowsLength, position);
        commitSoon();
        notifyLoaded(at, position);
        refresh.local = position;
        runFetchRef.current({ start: serverPosition, end: serverPosition + size }, step.cursor);
        return;
      }
      seq.refresh = null;
      seq.ended = step.ended;
      seq.length = position;
      seq.offset = serverPosition;
      core.loaded = position > 0 ? [{ start: 0, end: position }] : [];
      const tail = skeletonCount({ loaded: serverPosition, blockSize: size, count: seq.sentCount, ended: step.ended });
      if (refresh) core.pending.push({ start: position, rows: new Array<TData | undefined>(tail).fill(undefined), guard: null, mark: guard.mark });
      core.rowsLength = position + tail;
      setLoadedCount(position);
      setSkeletons(tail);
      setCount(seq.sentCount ?? (step.ended ? position : null));
      commitSoon();
      notifyLoaded(at, position);
    },
    [getCore, warn, commitSoon, blockSize, notifyLoaded, protectedRows, savedSince],
  );

  const land = useCallback(
    (range: RowRange, answer: unknown, sentCursor: unknown, guard: Guard) => {
      const core = getCore();
      const read = readAnswer<TData, unknown>(answer, range, warn, live.current.options.getRowId);
      if (core.kind === "unknown") core.kind = startsSequence(read) ? "sequence" : "random";
      if (core.kind === "sequence") {
        landSequence(range, read, sentCursor, guard);
        return;
      }
      const first = !core.ready;
      const nextCount = typeof read.totalRowCount === "number" ? read.totalRowCount : (core.count ?? range.start + read.rows.length);
      const refire = first || nextCount !== core.count;
      let keep: { displaced: Map<string, TData>; orphans: Map<string, { row: TData; slot: number }>; guarded: ProtectedRows; ranges: RowRange[] } | null = null;
      if (!first && nextCount !== core.count) {
        abortRequestsExcept(core, range);
        keep = { displaced: new Map(), orphans: core.orphans, guarded: unionIds(unionIds(guard.ids, savedSince(guard.mark)), protectedRows()), ranges: mergeRanges([...core.loaded, ...core.stale]) };
        core.loaded = [];
        core.failed.clear();
        core.pending.length = 0;
        forgetStructural();
        core.cancelQueuedRefresh?.();
        core.cancelQueuedRefresh = null;
        core.displaced = keep.displaced;
        core.stale = [];
        core.empty = [];
        core.cleared.clear();
        core.cancelFrame?.();
        core.cancelFrame = null;
      }
      if (first) core.ready = true;
      if (core.rowsLength !== nextCount || (!first && nextCount !== core.count)) {
        const idOf = live.current.options.getRowId;
        setRows((prev) => {
          if (keep !== null && keep.guarded !== null) stashGuardedRows(prev, keep.ranges, keep.guarded, keep.displaced, idOf, keep.orphans);
          return new Array<TData | undefined>(nextCount);
        });
        core.rowsLength = nextCount;
      } else {
        setRows((prev) => (prev.length === nextCount ? prev : Object.assign(prev.slice(0, nextCount), { length: nextCount })));
      }
      core.count = nextCount;
      setCount(nextCount);
      if (refire) setLoadedCount(0);

      const expected = Math.min(range.end, nextCount) - range.start;
      const written = Math.max(0, Math.min(read.rows.length, expected));
      if (read.rows.length < expected) {
        warn("short", `fetchRows returned ${read.rows.length} rows for rows [${range.start}, ${Math.min(range.end, nextCount)}); only those rows count as loaded and the rest stay unloaded`);
      }
      for (const [key, failure] of core.failed) {
        if (failure.range.start < range.start + written && range.start < failure.range.end) core.failed.delete(key);
      }
      if (core.failed.size === 0) setError(null);
      if (written > 0) {
        const idOf = live.current.options.getRowId;
        const blank: RowRange[] = [];
        const rows = read.rows.slice(0, written).map((row, index) => {
          if (row !== undefined && !core.deleted.has(idOf(row, range.start + index))) return row;
          blank.push({ start: range.start + index, end: range.start + index + 1 });
          return undefined;
        });
        const answered = { start: range.start, end: range.start + written };
        core.loaded = mergeRanges([...core.loaded, ...subtractRanges(answered, blank)]);
        core.empty = mergeRanges([...core.empty.flatMap((empty) => subtractRanges(empty, [answered])), ...blank]);
        core.stale = core.stale.flatMap((stale) => subtractRanges(stale, [answered]));
        setLoadedCount(sumRangeSizes(core.loaded));
        core.pending.push({ start: range.start, rows, guard: guard.ids, mark: guard.mark, final: core.inFlight.size <= 1 });
        commitSoon();
        notifyLoaded(range.start, range.start + written);
      }
      if (refire && core.lastWindow) windowRef.current(core.lastWindow);
    },
    [getCore, warn, commitSoon, landSequence, notifyLoaded, protectedRows, savedSince, forgetStructural],
  );

  const runFetch = useCallback(
    (range: RowRange, cursor?: unknown) => {
      const core = getCore();
      const key = rangeKey(range);
      if (core.inFlight.has(key)) return;
      const controller = new AbortController();
      const guard: Guard = { ids: savingRows(), mark: saveMark() };
      core.inFlight.set(key, { range, controller, guard });
      setLoading(true);
      const settle = () => {
        if (core.inFlight.get(key)?.controller !== controller) return;
        core.inFlight.delete(key);
        release(core);
        // Rows still waiting for the next frame count as loading, so "ready" means the rows are on screen.
        setLoading(core.inFlight.size > 0 || core.pending.length > 0);
      };
      const fail = (cause: unknown) => {
        if (controller.signal.aborted) return;
        const failure = cause ?? new Error("fetchRows rejected");
        core.failed.set(key, { range, cursor, error: failure });
        setError(failure);
        const onError = live.current.options.onError;
        if (onError) isolate("onError", () => onError(failure));
      };
      const request = { spec: live.current.spec, start: range.start, end: range.end, cursor, signal: controller.signal } as ServerRowsRequest<TCursor>;
      let landed = false;
      // A landed sequential block re-checks the rendered window once its request has settled, so the chain goes on while the window stays near the end.
      const afterSettle = () => {
        settle();
        if (landed && !controller.signal.aborted && core.kind === "sequence" && core.lastWindow) windowRef.current(core.lastWindow);
      };
      try {
        live.current.options
          .fetchRows(request)
          .then((answer) => {
            if (controller.signal.aborted) return;
            land(range, answer, cursor, guard);
            landed = true;
          })
          .catch(fail)
          .finally(afterSettle);
      } catch (cause) {
        fail(cause);
        settle();
      }
    },
    [getCore, land, savingRows, saveMark, release],
  );
  useLayoutEffect(() => {
    runFetchRef.current = runFetch;
  }, [runFetch]);

  const onRenderedRowsChange = useCallback(
    (range: RowRange) => {
      const core = getCore();
      core.lastWindow = range;
      if (core.ready && core.kind === "sequence") {
        const { seq } = core;
        if (seq.ended || seq.refresh || core.inFlight.size > 0 || !needsNextBlock(range, seq.length, overscanOf())) return;
        runFetch({ start: seq.offset, end: seq.offset + blockSize() }, seq.cursor);
        return;
      }
      if (!core.ready || core.count === null) return;
      const size = blockSize();
      const expanded = expandRange(range, { overscan: overscanOf(), blockSize: size, total: core.count });
      if (rangeSize(expanded) === 0) return;
      const covered = [...core.loaded, ...core.empty, ...Array.from(core.inFlight.values(), (entry) => entry.range)];
      for (const gap of subtractRanges(expanded, covered)) {
        for (const block of chunkRange(gap, size)) runFetch(block);
      }
    },
    [getCore, runFetch, blockSize, overscanOf],
  );
  useLayoutEffect(() => {
    windowRef.current = onRenderedRowsChange;
  }, [onRenderedRowsChange]);

  const specKey = serverSpecKey(spec);
  useLayoutEffect(() => {
    const core = getCore();
    const wasSequence = core.kind === "sequence";
    dropBlocks(wasSequence ? 0 : (core.count ?? 0));
    if (wasSequence) {
      core.count = null;
      setCount(null);
    }
    core.ready = false;
    setLoading(true);
    setError(null);
    // The first request waits a tick, so a StrictMode remount and a spec restored in a mount effect replace it before it leaves.
    const timer = setTimeout(() => runFetch({ start: 0, end: blockSize() }), 0);
    return () => {
      clearTimeout(timer);
      abortRequests();
      core.cancelFrame?.();
      core.cancelFrame = null;
    };
    // `specKey` stands for the spec content.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [specKey]);

  const evict = useCallback(
    (range: RowRange) => {
      const core = getCore();
      if (core.kind === "sequence") return;
      const start = Math.max(0, range.start);
      const end = Math.min(core.count ?? 0, range.end);
      if (end <= start) return;
      commit();
      const kept: RowRange[] = [];
      const cleared: RowRange[] = [];
      for (const loaded of mergeRanges([...core.loaded, ...core.stale])) {
        const overlap = { start: Math.max(start, loaded.start), end: Math.min(end, loaded.end) };
        if (overlap.end > overlap.start) cleared.push(overlap);
      }
      for (const loaded of core.loaded) kept.push(...subtractRanges(loaded, [{ start, end }]));
      core.stale = core.stale.flatMap((stale) => subtractRanges(stale, [{ start, end }]));
      core.empty = core.empty.flatMap((empty) => subtractRanges(empty, [{ start, end }]));
      core.loaded = mergeRanges(kept);
      setLoadedCount(sumRangeSizes(core.loaded));
      if (cleared.length === 0) return;
      setRows((prev) => {
        const next = prev.slice();
        for (const { start: from, end: to } of cleared) next.fill(undefined, from, to);
        return next;
      });
    },
    [getCore, commit],
  );

  const retry = useCallback(() => {
    const core = getCore();
    if (core.failed.size === 0) return;
    const failures = Array.from(core.failed.values());
    core.failed.clear();
    setError(null);
    for (const { range, cursor } of failures) runFetch(range, cursor);
  }, [getCore, runFetch]);

  // A protected row that left its old slot must not leave the slot marked loaded; the next window fetches it again.
  useLayoutEffect(() => {
    const core = getCore();
    if (core.cleared.size === 0) return;
    const slots = Array.from(core.cleared);
    core.cleared.clear();
    if (core.kind === "sequence") return;
    core.loaded = mergeRanges(slots.reduce<RowRange[]>((kept, slot) => kept.flatMap((range) => subtractRanges(range, [{ start: slot, end: slot + 1 }])), core.loaded));
    setLoadedCount(sumRangeSizes(core.loaded));
    if (core.lastWindow) windowRef.current(core.lastWindow);
  }, [rows, getCore]);

  const refresh = useCallback(() => {
    const core = getCore();
    if (!core.ready || (core.kind !== "sequence" && core.count === null)) {
      runFetch({ start: 0, end: blockSize() });
      return;
    }
    if (guardMissing()) warn("guard", GUARD_MISSING_MESSAGE);
    commit();
    const size = blockSize();
    if (core.kind === "sequence") {
      abortRequests();
      core.failed.clear();
      setError(null);
      core.seq.seen = new Set();
      core.seq.refresh = { keepUntil: Math.max(size, (core.lastWindow?.end ?? 0) + overscanOf()), local: 0 };
      runFetch({ start: 0, end: size });
      return;
    }
    const keep = core.lastWindow ? expandRange(core.lastWindow, { overscan: overscanOf(), blockSize: size, total: core.count! }) : { start: 0, end: Math.min(size, core.count!) };
    abortRequests();
    core.failed.clear();
    core.empty = [];
    setError(null);
    for (const outside of subtractRanges({ start: 0, end: core.count! }, [keep])) evict(outside);
    for (const block of chunkRange(keep, size)) runFetch(block);
  }, [getCore, runFetch, evict, abortRequests, blockSize, overscanOf, guardMissing, warn, commit]);

  const refreshRef = useRef<() => void>(noop);
  useLayoutEffect(() => {
    refreshRef.current = refresh;
  }, [refresh]);

  useEffect(() => {
    const core = getCore();
    setSettleListener(() => {
      if (core.kind !== "sequence") refreshRef.current();
    });
    return () => {
      setSettleListener(null);
      core.cancelQueuedRefresh?.();
      core.cancelQueuedRefresh = null;
    };
  }, [getCore, setSettleListener]);

  const getLoadedRanges = useCallback(() => getCore().loaded.slice(), [getCore]);

  const getRowId = useCallback((row: TData, index: number) => (row === undefined ? holeRowId(index) : live.current.options.getRowId(row, index)), []);

  // An insert or delete moves the end of the loaded rows; the next block starts after it.
  const followRowOperations = useCallback(
    (change: DataChange<TData>) => {
      const core = getCore();
      const { seq } = core;
      let delta = 0;
      for (const op of change.ops) delta += op.type === "insert" ? 1 : op.type === "delete" ? -1 : 0;
      if (delta === 0) return;
      seq.length = Math.max(0, seq.length + delta);
      seq.offset = Math.max(0, seq.offset + delta);
      core.rowsLength = Math.max(0, core.rowsLength + delta);
      core.loaded = seq.length > 0 ? [{ start: 0, end: seq.length }] : [];
      setLoadedCount(seq.length);
      if (seq.ended && seq.sentCount === null) setCount(seq.length);
    },
    [getCore],
  );

  const onDataChange = useCallback(
    (next: readonly TData[], change: DataChange<TData>) => {
      const core = getCore();
      markEdited();
      commit();
      // `next` is the grid's snapshot and can predate rows a landed block wrote; replaying the operations on the latest rows keeps them.
      setRows((prev) => {
        if (isDev() && !core.warned.has("dropped")) warnDroppedEdit(prev, change, live.current.options.getRowId, warn);
        return change.ops.length > 0 ? (applyChange(prev as TData[], change, getRowId) as (TData | undefined)[]) : (next.slice() as (TData | undefined)[]);
      });
      if (core.kind === "sequence") followRowOperations(change);
      trackDeletes(core.deleted, change);
      if (core.kind !== "sequence" && core.ready && change.ops.some((op) => op.type !== "update")) {
        // A local insert, delete, or move shifts rows away from the positions the loaded ranges name; the refresh loads the rendered ones again.
        const inserted = change.ops.filter((op) => op.type === "insert").length;
        core.stale = mergeRanges([...core.stale, ...core.loaded].map((range) => ({ start: range.start, end: range.end + inserted })));
        core.loaded = [];
        setLoadedCount(0);
        // A burst of row operations refreshes once, on the next frame.
        if (core.cancelQueuedRefresh === null) {
          core.cancelQueuedRefresh = scheduleFrame(() => {
            core.cancelQueuedRefresh = null;
            refreshRef.current();
          });
        }
      }
      const onDataChange = live.current.options.onDataChange;
      if (onDataChange) isolate("onDataChange", () => onDataChange(next, change));
    },
    [getCore, commit, getRowId, warn, followRowOperations, markEdited],
  );

  const providerProps = useMemo<UseDataGridServerRowsScrollProviderProps<TData>>(
    () => ({
      data: rows as TData[],
      getRowId,
      onDataChange,
      onRenderedRowsChange,
      sortMode: "server",
      filterMode: "server",
      sortState: spec.sorts as SortSpec[],
      onSortChange,
      filterState: spec.filters as FilterNode[],
      onFilterChange,
      searchText: spec.searchText,
      onSearchTextChange,
      totalRowCount: count,
      keepCheckedRows: true,
      plugins,
    }),
    [rows, count, spec, getRowId, onDataChange, onRenderedRowsChange, onSortChange, onFilterChange, onSearchTextChange, plugins],
  );
  const rootProps = useMemo<UseDataGridServerRowsRootProps>(() => ({ loading, error, onRetry: retry }), [loading, error, retry]);
  const gridProps = useMemo(() => ({ ...providerProps, ...rootProps }), [providerProps, rootProps]);

  const status = error !== null ? "error" : loading ? "loading" : "ready";
  const unloadedCount = skeletons ?? (count ?? 0) - loadedCount;
  return { gridProps, providerProps, rootProps, spec, totalRowCount: count, status, loading, error, retry, refresh, unloadedCount, getLoadedRanges, evict };
}

function noop() {}

function abortRequestsExcept<TData>(core: Core<TData>, keep: RowRange) {
  const keepKey = rangeKey(keep);
  for (const [key, { controller }] of core.inFlight) {
    if (key === keepKey) continue;
    controller.abort();
    core.inFlight.delete(key);
  }
}

function warnDroppedEdit<TData>(prev: readonly (TData | undefined)[], change: DataChange<TData>, getRowId: (row: TData, index: number) => string, warn: (kind: string, message: string) => void) {
  const missing = new Map<string, string>();
  for (const op of change.ops) if (op.type !== "insert") missing.set(op.rowId, op.rowId);
  if (missing.size === 0) return;
  // `some` skips holes and stops once every edited row is found, so a normal edit scans only up to its rows.
  prev.some((row, index) => {
    if (row !== undefined) missing.delete(getRowId(row, index));
    return missing.size === 0;
  });
  const dropped = missing.values().next();
  if (!dropped.done) warn("dropped", `an edit to row "${dropped.value}" was dropped because the row was evicted before the change merged; this hook does not own persistence, so keep the edit in your own cache`);
}

import type { RowRange } from "@/registry/default/components/data-grid/data-grid";
import { MAX_ROW_COUNT, type ReadAnswer } from "./read-answer";

/** Whether the first answer makes the source sequential: it carries a cursor, or it carries no count to size random access. */
export function startsSequence(read: Pick<ReadAnswer<unknown, unknown>, "nextCursor" | "totalRowCount">): boolean {
  return read.nextCursor !== undefined || typeof read.totalRowCount !== "number";
}

const MAX_CURSOR_KEY_LENGTH = 1024;
/** Cursors a chain remembers; a longer chain stops recording and relies on the `Object.is` check. */
export const MAX_SEEN_CURSORS = 10_000;

/** A stable key for comparing cursors by content; `null` for a cursor too large or not serializable to key. */
export function cursorKey(cursor: unknown): string | null {
  if (cursor === null || cursor === undefined) return null;
  if (typeof cursor !== "object") {
    const key = `${typeof cursor}:${String(cursor)}`;
    return key.length <= MAX_CURSOR_KEY_LENGTH ? key : null;
  }
  try {
    const json = JSON.stringify(cursor);
    return json !== undefined && json.length <= MAX_CURSOR_KEY_LENGTH ? `json:${json}` : null;
  } catch {
    return null;
  }
}

export type SequenceStep<TCursor> = {
  ended: boolean;
  /** The cursor the next block sends. */
  cursor: TCursor | undefined;
  warning: { kind: string; message: string } | null;
};

type StepInput<TCursor> = {
  read: ReadAnswer<unknown, TCursor>;
  /** The cursor this block was requested with. */
  sentCursor: TCursor | undefined;
  /** Rows loaded once this block is written. */
  loaded: number;
  /** The count the server sent, if any. */
  count: number | null;
  /** Keys of the cursors this chain already returned. */
  seenCursors?: ReadonlySet<string>;
};

/** Decides what a landed block means for the chain: does it go on, and with which cursor. */
export function stepSequence<TCursor>({ read, sentCursor, loaded, count, seenCursors }: StepInput<TCursor>): SequenceStep<TCursor> {
  const cursor = read.nextCursor ?? undefined;
  const end = (warning: SequenceStep<TCursor>["warning"] = null): SequenceStep<TCursor> => ({ ended: true, cursor, warning });
  if (read.rows.length === 0) {
    const emptyWithCursor = read.nextCursor !== undefined && read.nextCursor !== null;
    return end(emptyWithCursor ? { kind: "empty", message: "fetchRows returned an empty block with a next cursor; an empty block ends the source, so return rows or a null cursor" } : null);
  }
  if (read.nextCursor === null || read.hasMoreSent === false) return end();
  if (read.nextCursor === undefined && !read.hasMore) return end();
  if (read.nextCursor !== undefined && Object.is(read.nextCursor, sentCursor)) {
    return end({ kind: "cursor", message: "fetchRows answered the cursor it was sent; the source ends here, so return a new cursor or null" });
  }
  const key = cursorKey(read.nextCursor);
  if (key !== null && seenCursors?.has(key)) {
    return end({ kind: "cursor", message: "fetchRows returned a cursor it returned before; the source ends here, so return a new cursor or null" });
  }
  if (count !== null && loaded >= count) return end();
  if (loaded >= MAX_ROW_COUNT) return end({ kind: "max", message: `the source loaded ${MAX_ROW_COUNT} rows; it ends here` });
  return { ended: false, cursor, warning: null };
}

/** Skeleton rows below the loaded rows: one block, cut to the rows the server still owes. */
export function skeletonCount({ loaded, blockSize, count, ended }: { loaded: number; blockSize: number; count: number | null; ended: boolean }): number {
  if (ended) return 0;
  const owed = count === null ? blockSize : Math.max(0, count - loaded);
  return Math.min(blockSize, owed, Math.max(0, MAX_ROW_COUNT - loaded));
}

/** The next block starts when the rendered rows come within `overscan` of the loaded end. */
export function needsNextBlock(window: RowRange, loaded: number, overscan: number): boolean {
  return window.end + overscan >= loaded;
}

"use client";

import { useCallback, useEffect, useState } from "react";
import type { DataGridPlugin, DataGridReadState, DataGridStoreWrapper } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";

/**
 * The rule: a block that lands (refresh, retry or window load) replaces every row it carries, except a row that has a pending
 * cell edit or a save that was in flight at any moment since the request was sent: that row keeps its local value. A row with
 * a pending delete is gone: the answer's copy is dropped and its slot stays empty. A protected row that the answer lacks, such as a
 * pending insert, returns to its own slot when no answer row sits there; otherwise it is hidden, and a counted source refreshes
 * when no pending insert or delete is left. A pages refresh appends such a row at the page end (the page can exceed `pageSize`
 * by pending inserts); a sequential refresh that ends before a pending insert may drop it until its save settles.
 * Everything else is replaced. A block shows each id once (the first row of a repeated id in an answer wins) and leaves no hole in its
 * loaded range; rows that moved on the server can mix with older rows until the next refresh settles.
 */

/** The rows an answer must not overwrite: a save is pending, or an edit session is open. */
export type ProtectedRows = ReadonlySet<string> | null;

type Holder = {
  store: DataGridStoreWrapper | null;
  everMounted: boolean;
  edited: boolean;
  generation: number;
  /** Saves are tracked only while a request is open. */
  recording: boolean;
  /** Row id -> generation of its latest save start; holds one entry per saved row, dropped when no request is open. */
  savedAt: Map<string, number>;
  /** Rows of a local insert or delete whose save is pending. */
  structural: Set<string>;
  /** Called when the last pending insert or delete save settled. */
  onStructuralSettled: (() => void) | null;
};

function setListenerOn(holder: Holder, listener: (() => void) | null) {
  holder.onStructuralSettled = listener;
}

function trackStructural(holder: Holder, change: { source: string; ops: readonly { type: string; rowId: string }[] }) {
  if (change.source === "stream" || change.source === "rollback") return;
  const status = holder.store?.getState().saveStatus;
  for (const op of change.ops) if ((op.type === "insert" || op.type === "delete") && status?.get(op.rowId) === "saving") holder.structural.add(op.rowId);
}

function markEditedOn(holder: Holder) {
  holder.edited = true;
}

function trackSaves(holder: Holder, state: DataGridReadState, prev: DataGridReadState) {
  if (state.saveStatus === prev.saveStatus) return;
  if (holder.structural.size > 0) {
    for (const [id, status] of prev.saveStatus) {
      if (status === "saving" && state.saveStatus.get(id) !== "saving" && holder.structural.delete(id) && holder.structural.size === 0) holder.onStructuralSettled?.();
    }
  }
  if (!holder.recording) return;
  for (const [id, status] of state.saveStatus) {
    if (status === "saving" && prev.saveStatus.get(id) !== "saving") holder.savedAt.set(id, ++holder.generation);
  }
}

function savedSinceOn(holder: Holder, generation: number): ProtectedRows {
  let ids: Set<string> | null = null;
  for (const [id, at] of holder.savedAt) if (at > generation) (ids ??= new Set()).add(id);
  return ids;
}

function markSavesOn(holder: Holder): number {
  holder.recording = true;
  return holder.generation;
}

function pruneSavesOn(holder: Holder, oldestGeneration: number | null) {
  holder.recording = oldestGeneration !== null;
  if (oldestGeneration === null) holder.savedAt.clear();
  else for (const [id, at] of holder.savedAt) if (at <= oldestGeneration) holder.savedAt.delete(id);
}

function createGuardPlugin(holder: Holder): DataGridPlugin<unknown> {
  function RefreshGuardMount() {
    const store = useDataGridStoreApi();
    useEffect(() => {
      holder.store = store;
      holder.everMounted = true;
      const unsubscribe = store.subscribe((state, prev) => trackSaves(holder, state, prev));
      return () => {
        unsubscribe();
        holder.store = null;
      };
    }, [store]);
    return null;
  }
  return { name: "server-rows-refresh-guard", Mount: RefreshGuardMount, onDataChange: (_next, change) => trackStructural(holder, change) };
}

/** A plugin that gives the hook, which sits outside the provider, read access to the grid's save status and edit session. */
export function useRefreshGuard() {
  const [holder] = useState<Holder>(() => ({ store: null, everMounted: false, edited: false, generation: 0, recording: false, savedAt: new Map(), structural: new Set(), onStructuralSettled: null }));
  const [plugins] = useState(() => [createGuardPlugin(holder)]);
  const savingRows = useCallback((): ProtectedRows => {
    const state = holder.store?.getState();
    if (!state) return null;
    const ids = new Set<string>();
    for (const [rowId, status] of state.saveStatus) if (status === "saving") ids.add(rowId);
    return ids.size > 0 ? ids : null;
  }, [holder]);
  const protectedRows = useCallback((): ProtectedRows => {
    const editing = holder.store?.getState().editing;
    return editing ? unionIds(savingRows(), new Set([editing.rowId])) : savingRows();
  }, [holder, savingRows]);
  const guardMissing = useCallback(() => holder.edited && !holder.everMounted, [holder]);
  const markEdited = useCallback(() => markEditedOn(holder), [holder]);
  const saveMark = useCallback(() => markSavesOn(holder), [holder]);
  const savedSince = useCallback((mark: number) => savedSinceOn(holder, mark), [holder]);
  const setSettleListener = useCallback((listener: (() => void) | null) => setListenerOn(holder, listener), [holder]);
  const forgetStructural = useCallback(() => holder.structural.clear(), [holder]);
  const pruneSaves = useCallback((oldestMark: number | null) => pruneSavesOn(holder, oldestMark), [holder]);
  return { plugins, protectedRows, savingRows, guardMissing, markEdited, saveMark, savedSince, pruneSaves, setSettleListener, forgetStructural };
}

export const GUARD_MISSING_MESSAGE =
  "refresh cannot protect rows with a pending save or an open edit because the refresh guard plugin never mounted; if you pass your own `plugins` prop to the provider, put ...gridProps.plugins first in it";

/** Applies the rule to an incoming page: a deleted row is dropped, a protected row keeps its local value by id, and a protected row the page lacks stays at the end. */
export function keepProtectedRows<TData>(
  incoming: readonly TData[],
  current: readonly TData[],
  guarded: ProtectedRows,
  deleted: ReadonlySet<string>,
  keepMissing: boolean,
  idOf: (row: TData, index: number) => string,
): TData[] {
  if (guarded === null && deleted.size === 0) return incoming as TData[];
  const local = new Map<string, TData>();
  current.forEach((row, index) => {
    const id = idOf(row, index);
    if (guarded?.has(id)) local.set(id, row);
  });
  const placed = new Set<string>();
  const page: TData[] = [];
  incoming.forEach((row, index) => {
    const id = idOf(row, index);
    if (deleted.has(id)) return;
    placed.add(id);
    page.push(local.get(id) ?? row);
  });
  if (keepMissing) for (const [id, row] of local) if (!placed.has(id) && !deleted.has(id)) page.push(row);
  return page;
}

/** Notes the rows a change deleted, and forgets a row that a change inserted again. */
export function trackDeletes(deleted: Set<string>, change: { ops: readonly { type: string; rowId: string }[] }) {
  for (const op of (change.ops as typeof change.ops | undefined) ?? []) {
    if (op.type === "delete") deleted.add(op.rowId);
    else if (op.type === "insert") deleted.delete(op.rowId);
  }
}

/** Drops the rows whose delete is no longer pending. */
export function pruneIds(ids: Set<string>, stillSaving: ProtectedRows) {
  for (const id of ids) if (!stillSaving?.has(id)) ids.delete(id);
}

/** The union of two protected sets; either may be `null`. */
export function unionIds(a: ProtectedRows, b: ProtectedRows): ProtectedRows {
  if (a === null) return b;
  if (b === null || a === b) return a;
  return new Set([...a, ...b]);
}

export type GuardedBlock<TData> = { start: number; rows: readonly (TData | undefined)[]; guard: ProtectedRows };

/** Moves the guarded rows in the given index ranges into `into`, for the block that brings their ids back. */
export function stashGuardedRows<TData>(
  rows: readonly (TData | undefined)[],
  ranges: readonly { start: number; end: number }[],
  guarded: ReadonlySet<string>,
  into: Map<string, TData>,
  idOf: (row: TData, index: number) => string,
  orphans: Map<string, { row: TData; slot: number }>,
) {
  for (const { start, end } of ranges) {
    for (let index = start; index < Math.min(end, rows.length); index++) {
      const row = rows[index];
      if (row !== undefined && guarded.has(idOf(row, index))) {
        into.set(idOf(row, index), row);
        orphans.set(idOf(row, index), { row, slot: index });
      }
    }
  }
}

function findSlot<TData>(rows: readonly (TData | undefined)[], ranges: readonly { start: number; end: number }[], id: string, idOf: (row: TData, index: number) => string, near: number): number {
  for (const index of [near - 1, near + 1]) {
    const row = rows[index];
    if (row !== undefined && idOf(row, index) === id) return index;
  }
  for (const { start, end } of ranges) {
    for (let index = start; index < Math.min(end, rows.length); index++) {
      const row = rows[index];
      if (row !== undefined && idOf(row, index) === id) return index;
    }
  }
  return -1;
}

/**
 * Writes blocks into a copy of `prev`. A block guards the ids it was requested with plus the `live` ones: such a row keeps its
 * local value and appears once, at the index the answer gives it. `displaced` holds a guarded row that an earlier block overwrote,
 * for the block that brings its id back. `cleared` lists the slots left empty because a row moved away from them.
 */
export function writeBlocks<TData>(
  prev: readonly (TData | undefined)[],
  blocks: readonly GuardedBlock<TData>[],
  live: ProtectedRows,
  displaced: Map<string, TData>,
  ranges: readonly { start: number; end: number }[],
  idOf: (row: TData, index: number) => string,
  memory: { orphans: Map<string, { row: TData; slot: number }>; carried: Set<string> },
  final = false,
): { rows: (TData | undefined)[]; cleared: number[] } {
  const next = prev.slice();
  const emptied: number[] = [];
  const { carried, orphans: overwritten } = memory;
  const stillProtected = new Set<string>();
  for (const { start, rows, guard } of blocks) {
    const guarded = unionIds(guard, live);
    if (guarded !== null) for (const id of guarded) stillProtected.add(id);
    for (let i = 0; i < rows.length && start + i < next.length; i++) {
      const slot = start + i;
      const incoming = rows[i];
      if (guarded === null) {
        next[slot] = incoming;
        continue;
      }
      const occupant = next[slot];
      const occupantId = occupant === undefined ? undefined : idOf(occupant, slot);
      const incomingId = incoming === undefined ? undefined : idOf(incoming, slot);
      if (incomingId !== undefined) carried.add(incomingId);
      if (incomingId !== undefined && guarded.has(incomingId)) {
        if (occupantId === incomingId) continue;
        if (occupantId !== undefined && guarded.has(occupantId)) {
          displaced.set(occupantId, occupant as TData);
          overwritten.set(occupantId, { row: occupant as TData, slot });
        }
        const from = findSlot(next, ranges, incomingId, idOf, slot);
        const local = from >= 0 ? next[from] : displaced.get(incomingId);
        next[slot] = local ?? incoming;
        if (local !== undefined && from >= 0) {
          next[from] = undefined;
          emptied.push(from);
        }
        continue;
      }
      if (occupantId !== undefined && guarded.has(occupantId)) {
        displaced.set(occupantId, occupant as TData);
        overwritten.set(occupantId, { row: occupant as TData, slot });
      }
      next[slot] = incoming;
    }
  }
  // Nothing else is loading: a protected row that the answer does not carry (a pending insert) returns to its own slot when no answer row sits there.
  if (final) {
    for (const [id, { row, slot }] of overwritten) {
      if (carried.has(id) || !stillProtected.has(id) || slot >= next.length || next[slot] !== undefined) continue;
      next[slot] = row;
    }
  }
  return { rows: next, cleared: emptied.filter((slot) => next[slot] === undefined) };
}

import type { RowRange, ServerSpec } from "@/registry/default/components/data-grid/data-grid";

/** Largest row count the server contract accepts; a bigger count clamps to it. */
export const MAX_ROW_COUNT = 10_000_000;

/** What `fetchRows` receives in every mode. */
export type ServerRowsRequest<TCursor = never> = {
  /** The sort, filter, and search of this request. */
  spec: ServerSpec;
  /** Index of the first requested row in the result. */
  start: number;
  /** One past the last requested row; `end - start` is the limit. */
  end: number;
  /** Sequential scroll only: the `nextCursor` of the block before; `undefined` for the first block and for every other source. */
  cursor: TCursor | undefined;
  /** Aborted when a newer request replaces this one, on a spec change, and on unmount. */
  signal: AbortSignal;
};

/** Pages mode adds the page address; `start` is `(page - 1) * pageSize`. */
export type ServerRowsPageRequest = ServerRowsRequest & {
  /** 1-based page. */
  page: number;
  pageSize: number;
};

/** What `fetchRows` resolves with in every mode. */
export type ServerRowsAnswer<TData, TCursor = never> = {
  /** At most `end - start` rows, in order from `start`; extra rows are dropped with a development warning. A repeated row id keeps its first row and leaves the later copy's slot empty (a skeleton row); make the sort total. */
  rows: TData[];
  /** Row count of the result. Omitted keeps the last known count; `null` declares it unknown. */
  totalRowCount?: number | null;
  /** Rows exist after this block. Default: the block came back full. Ignored when a count is known. */
  hasMore?: boolean;
  /** Cursor sources: passed back as `cursor`. `null` ends the source. */
  nextCursor?: TCursor | null;
};

/** An answer after validation. */
export type ReadAnswer<TData, TCursor = never> = {
  /** The answer's rows in order; a later copy of a repeated id is `undefined`, so the other rows keep their positions. */
  rows: (TData | undefined)[];
  /** `undefined` keeps the last known count. */
  totalRowCount: number | null | undefined;
  hasMore: boolean;
  /** The `hasMore` the answer carried, if any. */
  hasMoreSent: boolean | undefined;
  nextCursor: TCursor | null | undefined;
};

/**
 * Validates an untrusted answer: `rows` must be an array and is cut to the requested size, `totalRowCount` must be a
 * non-negative safe integer (else unknown) and clamps to {@link MAX_ROW_COUNT}. Throws when the answer has no rows array.
 */
export function readAnswer<TData, TCursor = never>(
  answer: unknown,
  range: RowRange,
  warn: (kind: string, message: string) => void,
  idOf?: (row: TData, index: number) => string,
): ReadAnswer<TData, TCursor> {
  const raw = answer as Partial<ServerRowsAnswer<TData, TCursor>> | null | undefined;
  if (!Array.isArray(raw?.rows)) throw new TypeError("fetchRows of useDataGridServerRows must resolve with { rows: TData[] }");
  const limit = range.end - range.start;
  let rows: (TData | undefined)[] = raw.rows;
  if (rows.length > limit) {
    warn("long", `fetchRows returned ${rows.length} rows for a request of ${limit}; only the first ${limit} are used`);
    rows = rows.slice(0, limit);
  }
  const legacy = raw as { total?: unknown; hasNextPage?: unknown };
  if (("total" in legacy && !("totalRowCount" in raw)) || "hasNextPage" in legacy) {
    warn("legacy", "the answer of fetchRows uses `total` or `hasNextPage`; rename them to `totalRowCount` and `hasMore`");
  }
  let totalRowCount: number | null | undefined;
  if (raw.totalRowCount === undefined) totalRowCount = undefined;
  else if (raw.totalRowCount === null) totalRowCount = null;
  else if (typeof raw.totalRowCount === "number" && Number.isSafeInteger(raw.totalRowCount) && raw.totalRowCount >= 0) {
    totalRowCount = Math.min(raw.totalRowCount, MAX_ROW_COUNT);
    if (totalRowCount !== raw.totalRowCount) warn("count", `totalRowCount ${raw.totalRowCount} is above ${MAX_ROW_COUNT}; using ${MAX_ROW_COUNT}`);
  } else {
    totalRowCount = null;
    warn("count", "totalRowCount must be a non-negative integer or null; treating the count as unknown");
  }
  const full = rows.length === limit;
  if (idOf) rows = firstCopies(rows as TData[], idOf, range.start, warn);
  return {
    rows,
    totalRowCount,
    hasMore: typeof raw.hasMore === "boolean" ? raw.hasMore : full,
    hasMoreSent: typeof raw.hasMore === "boolean" ? raw.hasMore : undefined,
    nextCursor: raw.nextCursor,
  };
}

/** Keeps the first row of each id and blanks the later copies, so one answer never puts the same id twice into the grid. */
function firstCopies<TData>(rows: TData[], idOf: (row: TData, index: number) => string, start: number, warn: (kind: string, message: string) => void): (TData | undefined)[] {
  const seen = new Set<string>();
  let repeated = false;
  const kept = rows.map((row, index) => {
    const id = idOf(row, start + index);
    if (seen.has(id)) {
      repeated = true;
      return undefined;
    }
    seen.add(id);
    return row;
  });
  if (repeated) warn("duplicate", "fetchRows returned a duplicate row id; only the first row of each id is used, so make the sort total (add the row id as a last sort key)");
  return kept;
}

"use client";

import { useCallback, useLayoutEffect, useRef, useState } from "react";
import type { FilterNode, ServerSpec, SortSpec } from "@/registry/default/components/data-grid/data-grid";

/** The request state every mode of `useDataGridServerRows` returns. */
export type DataSourceState = {
  /** `"error"` wins over `"loading"`. */
  status: "loading" | "error" | "ready";
  /** A request of the current spec is in flight. */
  loading: boolean;
  /** The latest failure of the current spec, or `null`. */
  error: unknown;
  /** Repeats the failed requests. Does nothing without an error. */
  retry: () => void;
  /** Fetches what is in view again and keeps it on screen until the answer lands. */
  refresh: () => void;
};

const EMPTY_SPEC: ServerSpec = { sorts: [], filters: [], searchText: "" };

/** Controlled or uncontrolled state with a stable setter that always calls the latest `onChange`. */
export function useControlled<T>(controlled: T | undefined, initial: () => T, onChange: ((next: T) => void) | undefined) {
  const [inner, setInner] = useState(initial);
  const latest = useRef({ controlled, onChange });
  useLayoutEffect(() => {
    latest.current = { controlled, onChange };
  });
  const set = useCallback((next: T) => {
    if (latest.current.controlled === undefined) setInner(next);
    latest.current.onChange?.(next);
  }, []);
  return [controlled ?? inner, set] as const;
}

/** Runs a consumer callback so that a throw cannot break the caller's bookkeeping. */
export function isolate(label: string, call: () => void) {
  try {
    call();
  } catch (error) {
    console.error(`[data-grid-server] ${label} threw`, error);
  }
}

export type ServerSpecOptions = {
  spec?: ServerSpec;
  defaultSpec?: Partial<ServerSpec>;
  onSpecChange?: (spec: ServerSpec) => void;
};

/** The sort, filter, and search of a server source, with stable change handlers for the grid's controlled state. */
export function useServerSpec(source: ServerSpecOptions, afterChange: () => void) {
  const [spec, setSpec] = useControlled<ServerSpec>(
    source.spec,
    () => ({
      sorts: [...(source.defaultSpec?.sorts ?? EMPTY_SPEC.sorts)],
      filters: [...(source.defaultSpec?.filters ?? EMPTY_SPEC.filters)],
      searchText: source.defaultSpec?.searchText ?? EMPTY_SPEC.searchText,
    }),
    source.onSpecChange,
  );
  const live = useRef({ spec, afterChange });
  useLayoutEffect(() => {
    live.current = { spec, afterChange };
  });
  const changeSpec = useCallback(
    (next: Partial<ServerSpec>) => {
      const merged = { ...live.current.spec, ...next };
      // Two changes in one effect (a URL restore) merge instead of overwriting each other.
      live.current.spec = merged;
      setSpec(merged);
      live.current.afterChange();
    },
    [setSpec],
  );
  const onSortChange = useCallback((sorts: SortSpec[]) => changeSpec({ sorts }), [changeSpec]);
  const onFilterChange = useCallback((filters: FilterNode[]) => changeSpec({ filters }), [changeSpec]);
  const onSearchTextChange = useCallback((searchText: string) => changeSpec({ searchText }), [changeSpec]);
  return { spec, onSortChange, onFilterChange, onSearchTextChange };
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";
import { serverSpecKey, type DataChange, type DataGridPlugin, type FilterNode, type RowRange, type ServerSpec, type SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridPagination, type DataGridPaginationControls } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { DEFAULT_PAGE_SIZES } from "@/registry/default/components/data-grid-pagination/pagination-math";
import { MAX_ROW_COUNT, readAnswer, type ServerRowsAnswer, type ServerRowsPageRequest } from "./read-answer";
import { useScrollBlocks, type UseDataGridServerRowsScrollOptions, type UseDataGridServerRowsScrollResult } from "./scroll-blocks";
import { GUARD_MISSING_MESSAGE, keepProtectedRows, pruneIds, trackDeletes, unionIds, useRefreshGuard } from "./refresh-guard";
import { isolate, useControlled, useServerSpec } from "./server-state";

export type { DataSourceState } from "./server-state";
export type { ServerRowsAnswer, ServerRowsPageRequest, ServerRowsRequest } from "./read-answer";
export type { UseDataGridServerRowsScrollOptions, UseDataGridServerRowsScrollProviderProps, UseDataGridServerRowsScrollResult } from "./scroll-blocks";

/** Options of {@link useDataGridServerRows} in pages mode. */
export type UseDataGridServerRowsOptions<TData> = {
  /** `"pages"` fetches one page per state and drives `pager`. Fixed for the life of the hook. Default `"pages"`. */
  mode?: "pages";
  getRowId: (row: TData, index: number) => string;
  fetchRows: (request: ServerRowsPageRequest) => Promise<ServerRowsAnswer<TData>>;
  /** Rows per page while `pageSize` is not controlled. Default: the first of `pageSizeOptions`. */
  defaultPageSize?: number;
  /** Controls the page size; pair it with `onPageSizeChange`. */
  pageSize?: number;
  onPageSizeChange?: (pageSize: number) => void;
  /** Page sizes the footer offers. Default 10, 25, 50, 100. */
  pageSizeOptions?: readonly number[];
  /** First page while `page` is not controlled. Default 1. */
  defaultPage?: number;
  /** Controls the current page; pair it with `onPageChange`. */
  page?: number;
  onPageChange?: (page: number) => void;
  /** The sort, filter, and search while `spec` is not controlled. */
  defaultSpec?: Partial<ServerSpec>;
  /** Controls the sort, filter, and search; pair it with `onSpecChange`. */
  spec?: ServerSpec;
  onSpecChange?: (spec: ServerSpec) => void;
  /** Fires after a request fails. */
  onError?: (error: unknown) => void;
  /** Fires after the rows of a request land, with the range they cover. */
  onLoaded?: (range: RowRange) => void;
  /** Fires after the hook keeps an edit, insert, delete, or revert. Put your handler here; a spread override drops the merge. */
  onDataChange?: (next: readonly TData[], change: DataChange<TData>) => void;
};

/** Return value of {@link useDataGridServerRows}. */
export type UseDataGridServerRowsResult<TData> = {
  /** Spread onto `<DataGrid {...server.gridProps} columns={columns} />`. */
  gridProps: UseDataGridServerRowsProviderProps<TData> & UseDataGridServerRowsRootProps;
  /** The part of `gridProps` for `<DataGridProvider>` in a composed layout. */
  providerProps: UseDataGridServerRowsProviderProps<TData>;
  /** The part of `gridProps` for `<DataGridRoot>` in a composed layout: the loading flag and the error state. */
  rootProps: UseDataGridServerRowsRootProps;
  /** The sort, filter, and search text of the current request. */
  spec: ServerSpec;
  /** The row count of the result; `null` when the server sends none. */
  totalRowCount: number | null;
  /** Spread onto `<DataGridPaginationBar {...server.pager} />`. */
  pager: DataGridPaginationControls;
  /** `"error"` wins over `"loading"`. */
  status: "loading" | "error" | "ready";
  /** A request of the current spec is in flight. */
  loading: boolean;
  /** The failure of the current request, or `null`. It clears when a new request starts. */
  error: unknown;
  /** Repeats the request that failed. Does nothing without an error. */
  retry: () => void;
  /** Fetches the current page again and keeps the rows on screen until the answer lands. A block that lands (refresh, retry or window load) replaces every row it carries, except a row that has a pending cell edit or a save that was in flight at any moment since the request was sent: that row keeps its local value. A row with a pending delete is gone: the answer's copy is dropped and its slot stays empty. A protected row that the answer lacks, such as a pending insert, returns to its own slot when no answer row sits there; otherwise it is hidden, and a counted source refreshes when no pending insert or delete is left, so the server decides. A pages refresh appends such a row at the end of the page, so the page can exceed `pageSize` by pending inserts. A sequential refresh that ends before a pending insert may drop it until its save settles. A block shows each id once (the first row of a repeated id in an answer wins) and leaves no hole in its loaded range; rows that moved on the server can mix with older rows until the next refresh settles. Call it after the `onSave` promise settles to pick up server-computed fields. */
  refresh: () => void;
};

/** Props of {@link UseDataGridServerRowsResult.gridProps} that belong to `DataGridProvider`. */
export type UseDataGridServerRowsProviderProps<TData> = {
  data: readonly TData[];
  getRowId: (row: TData, index: number) => string;
  /** Keeps the rows in step with edits, inserts, deletes, and reverts of a refused save. Send changes to your API from `onSave`. */
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  sortMode: "server";
  filterMode: "server";
  sortState: SortSpec[];
  onSortChange: (next: SortSpec[]) => void;
  filterState: FilterNode[];
  onFilterChange: (next: FilterNode[]) => void;
  searchText: string;
  onSearchTextChange: (next: string) => void;
  /** The row count of the result; `null` when the server sends none. */
  totalRowCount: number | null;
  keepCheckedRows: true;
  /** Mounts the guard that keeps a refresh from overwriting a row with a pending save or an open edit. Put your own plugins after it. */
  plugins: readonly DataGridPlugin<unknown>[];
};

/** Props of {@link UseDataGridServerRowsResult.gridProps} that belong to `DataGridRoot`. */
export type UseDataGridServerRowsRootProps = {
  loading: boolean;
  error: unknown;
  onRetry: () => void;
};

type Settled<TData> = { key: string; view: string; rows: TData[]; totalRowCount: number | null; hasMore: boolean; error: unknown };

/**
 * One server data source for the grid. It owns the sort, filter, and search unless you control them, aborts the request a
 * newer state replaces, and keeps the last good rows on screen while the next request runs or after an error. The state is
 * the grid's controlled state, so it works outside the provider and needs no bridge component.
 *
 * `mode: "pages"` (default) fetches one page per state and goes back to page 1 when the spec or the page size changes.
 * `mode: "scroll"` fetches fixed-size blocks as the rendered rows move. An answer with `totalRowCount` makes it random access;
 * an answer with `nextCursor`, or with neither, makes it sequential: the loaded rows plus one block of skeletons.
 * The mode is fixed for the life of the hook.
 */
export function useDataGridServerRows<TData, TCursor = never>(options: UseDataGridServerRowsScrollOptions<TData, TCursor>): UseDataGridServerRowsScrollResult<TData>;
export function useDataGridServerRows<TData>(options: UseDataGridServerRowsOptions<TData>): UseDataGridServerRowsResult<TData>;
export function useDataGridServerRows<TData, TCursor = never>(options: UseDataGridServerRowsOptions<TData> | UseDataGridServerRowsScrollOptions<TData, TCursor>) {
  const firstMode = useRef({ mode: options.mode ?? "pages", warned: false });
  if (isDev() && !firstMode.current.warned && (options.mode ?? "pages") !== firstMode.current.mode) {
    firstMode.current.warned = true;
    console.warn(`[data-grid-server] mode changed from "${firstMode.current.mode}" to "${options.mode ?? "pages"}"; the mode is fixed for the life of the hook, so remount it with a key`);
  }
  // The mode never changes for a mounted hook, so each render calls the same hooks in the same order.
  // eslint-disable-next-line react-hooks/rules-of-hooks
  // oxlint-disable-next-line react-hooks/rules-of-hooks
  return options.mode === "scroll" ? useScrollBlocks(options) : usePagesRows(options);
}

function usePagesRows<TData>(options: UseDataGridServerRowsOptions<TData>): UseDataGridServerRowsResult<TData> {
  const { pageSizeOptions = DEFAULT_PAGE_SIZES } = options;
  const [pageSize, setPageSize] = useControlled(options.pageSize, () => options.defaultPageSize ?? pageSizeOptions[0] ?? DEFAULT_PAGE_SIZES[0], options.onPageSizeChange);
  const [rawPage, setPage] = useControlled(options.page, () => options.defaultPage ?? 1, options.onPageChange);
  const maxPage = Math.max(1, Math.ceil(MAX_ROW_COUNT / Math.max(1, pageSize)));
  const page = Number.isSafeInteger(rawPage) && rawPage >= 1 ? Math.min(rawPage, maxPage) : 1;
  const live = useRef({ options, page, pageSize, settledOnce: false, requested: false, error: null as unknown });
  const { spec, onSortChange, onFilterChange, onSearchTextChange } = useServerSpec(options, () => {
    if (live.current.settledOnce) setPage(1);
  });
  const [tick, setTick] = useState(0);
  const { plugins, protectedRows, guardMissing, markEdited, saveMark, savedSince, pruneSaves, savingRows } = useRefreshGuard();
  const [settled, setSettled] = useState<Settled<TData>>({ key: "", view: "", rows: [], totalRowCount: null, hasMore: false, error: null });

  const view = `${serverSpecKey(spec)}|${page}|${pageSize}`;
  const key = `${view}|${tick}`;
  const deleted = useRef(new Set<string>());

  const warned = useRef(new Set<string>());

  useEffect(() => {
    const controller = new AbortController();
    const { page: requestPage, pageSize: requestSize } = live.current;
    const requestSpec = spec;
    const protectedAtStart = savingRows();
    const markAtStart = saveMark();
    pruneSaves(markAtStart);
    pruneIds(deleted.current, protectedAtStart);
    const start = (requestPage - 1) * requestSize;
    const range: RowRange = { start, end: start + requestSize };
    const warn = (kind: string, message: string) => {
      if (!isDev() || warned.current.has(kind)) return;
      warned.current.add(kind);
      console.warn(`[data-grid-server] ${message}`);
    };
    const settleMountState = live.current.requested ? Promise.resolve() : new Promise<void>((resolve) => setTimeout(resolve, 0));
    live.current.requested = true;
    // A state restored in a mount effect (URL state) replaces this request before it leaves.
    settleMountState
      .then(() => {
        if (controller.signal.aborted) return Promise.reject(controller.signal.reason);
        return live.current.options.fetchRows({ spec: requestSpec, page: requestPage, pageSize: requestSize, start, end: range.end, cursor: undefined, signal: controller.signal });
      })
      .then((answer) => {
        if (controller.signal.aborted) return;
        const read = readAnswer<TData>(answer, range, warn, live.current.options.getRowId);
        live.current.settledOnce = true;
        const guarded = unionIds(unionIds(protectedAtStart, savedSince(markAtStart)), protectedRows());
        pruneSaves(null);
        setSettled((prev) => ({
          key,
          view,
          rows: keepProtectedRows(read.rows.filter((row) => row !== undefined) as TData[], prev.rows, guarded, deleted.current, prev.view === view, live.current.options.getRowId),
          totalRowCount: read.totalRowCount === undefined ? prev.totalRowCount : read.totalRowCount,
          hasMore: read.hasMore,
          error: null,
        }));
        const onLoaded = live.current.options.onLoaded;
        if (onLoaded) isolate("onLoaded", () => onLoaded({ start, end: start + read.rows.length }));
      })
      .catch((error: unknown) => {
        if (controller.signal.aborted) return;
        const failure = error ?? new Error("fetchRows rejected");
        live.current.settledOnce = true;
        pruneSaves(null);
        setSettled((prev) => ({ ...prev, key, error: failure }));
        const onError = live.current.options.onError;
        if (onError) isolate("onError", () => onError(failure));
      });
    return () => controller.abort();
    // `key` stands for spec, page, pageSize, and tick.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  const loading = settled.key !== key;
  const error = settled.key === key ? settled.error : null;
  useLayoutEffect(() => {
    Object.assign(live.current, { options, page, pageSize, error });
  });
  const status = error !== null ? "error" : loading ? "loading" : "ready";

  const specKey = serverSpecKey(spec);
  const seenSpecKey = useRef(specKey);
  const seenPage = useRef(page);
  useLayoutEffect(() => {
    const pageMoved = seenPage.current !== page;
    seenPage.current = page;
    if (seenSpecKey.current === specKey) return;
    seenSpecKey.current = specKey;
    // A spec the consumer changed from outside (browser back) lands here; a grid change already reset the page.
    if (live.current.settledOnce && !pageMoved && page !== 1) setPage(1);
  }, [specKey, page, setPage]);

  const retry = useCallback(() => {
    if (live.current.error !== null) setTick((n) => n + 1);
  }, []);
  const refresh = useCallback(() => {
    if (isDev() && live.current.settledOnce && guardMissing() && !warned.current.has("guard")) {
      warned.current.add("guard");
      console.warn(`[data-grid-server] ${GUARD_MISSING_MESSAGE}`);
    }
    setTick((n) => n + 1);
  }, [guardMissing]);

  const onDataChange = useCallback((next: readonly TData[], change: DataChange<TData>) => {
    markEdited();
    trackDeletes(deleted.current, change);
    setSettled((prev) => ({ ...prev, rows: next as TData[] }));
    live.current.options.onDataChange?.(next, change);
  }, [markEdited]);
  const getRowId = useCallback((row: TData, index: number) => live.current.options.getRowId(row, index), []);

  const onPageSizeChange = useCallback(
    (next: number) => {
      setPageSize(next);
      setPage(1);
    },
    [setPageSize, setPage],
  );
  const { pager } = useDataGridPagination({
    page,
    pageSize,
    pageSizeOptions,
    totalRowCount: settled.totalRowCount,
    hasNextPage: settled.hasMore,
    onPageChange: setPage,
    onPageSizeChange,
  });

  const providerProps = useMemo<UseDataGridServerRowsProviderProps<TData>>(
    () => ({
      data: settled.rows,
      getRowId,
      onDataChange,
      sortMode: "server",
      filterMode: "server",
      sortState: spec.sorts as SortSpec[],
      onSortChange,
      filterState: spec.filters as FilterNode[],
      onFilterChange,
      searchText: spec.searchText,
      onSearchTextChange,
      totalRowCount: settled.totalRowCount,
      keepCheckedRows: true,
      plugins,
    }),
    [settled.rows, settled.totalRowCount, spec, getRowId, onDataChange, onSortChange, onFilterChange, onSearchTextChange, plugins],
  );
  const rootProps = useMemo<UseDataGridServerRowsRootProps>(() => ({ loading, error, onRetry: retry }), [loading, error, retry]);
  const gridProps = useMemo(() => ({ ...providerProps, ...rootProps }), [providerProps, rootProps]);

  return { gridProps, providerProps, rootProps, spec, totalRowCount: settled.totalRowCount, pager, status, loading, error, retry, refresh };
}
